		return;
	case 0x84:
		if (*has_dvb && (usb_endpoint_xfer_bulk(e))) {
			*has_dvb = true;
			dev->dvb_ep_bulk = e->bEndpointAddress;
		} else if (*has_video && (usb_endpoint_xfer_bulk(e))) {
			dev->analog_ep_bulk = e->bEndpointAddress;
		} else {
			if (usb_endpoint_xfer_isoc(e)) {
